# model-nosofs: the recipe that fetches, builds and runs nosofs on a sandbox.
# Read by exportit/tools/export.py; described in exportit/MAP.md.
#
# One unit per model (stage 5, decision 1). The model's directory goes to the
# root of the unit, unchanged; files shared by several models are in model-common.

covers models/nosofs/
copy models/nosofs/    ./

# Files that exist only in the unit.
new UNIT.md        # what this unit is, where it came from, how it is checked
new LICENSE      # a copy of the repository's LICENSE
new Justfile
new tests/
